add('Settings','T36','Holiday calendars','HR admin · Ada',SP('Holidays','Holidays','Each person gets the holidays for the place they work. Weekends falling on a holiday follow the regional rules.',`${seg(['2026','2027'],0,{size:'sm'})}${btn('Add calendar',{icon:'plus'})}`,g('260px minmax(0,1fr)',[list([['Madrid','Spain + region + city','148'],['Barcelona','Spain + Catalonia','100'],['Berlin','Germany + Berlin','64'],['London','England','41'],['Remote','By home address','59']].map(([t,s,n],i,a)=>listRow({t,s,last:i===a.length-1,bg:i===0?'var(--r-accent-soft)':'',trail:`<span style="font: 500 13px/1 var(--r-font); color: var(--r-fg-3);">${n}</span>`}))),col([aiCard('2027 is ready to review',C([note('I read the official bulletins for Spain, Madrid and Catalonia and built the 2027 calendars. Two days aren’t confirmed by the city yet.'),R([btn('Review 2027',{size:'sm'}),badge('2 to confirm',{tone:'warning',size:'sm'})],{gap:10})],{gap:10}),{right:aiTag()}),table({dense:1,cols:[{l:'Date',w:'120px'},{l:'Holiday'},{l:'Applies to',w:'150px'}],rows:holRows.map(([d,n,a])=>[d,`<b>${n}</b>`,a])})])]),1080),'Layered calendars, national plus regional plus city, assigned by work location. The AI drafts next year from official sources and leaves the unconfirmed days for HR.');
